// Shared LendLoop signing scheme: hex(HMAC-SHA256(secret, `${timestamp}.${rawBody}`)), timestamp in unix seconds.
const crypto = require('crypto');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
if (!secret) throw new Error('LENDLOOP_WEBHOOK_SECRET is not set'); // fail closed
const sign = (rawBody) => {
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');
  return { timestamp, signature, rawBody };
};

// Data-minimized: no stack trace, no input data, message truncated.
const d = $input.first().json;
const report = {
  workflowName: d.workflow?.name ?? 'unknown',
  nodeName: d.execution?.lastNodeExecuted ?? undefined,
  message: String(d.execution?.error?.message ?? d.trigger?.error?.message ?? 'Unknown error').slice(0, 500),
  executionId: d.execution?.id != null ? String(d.execution.id) : undefined,
};
return [{ json: sign(JSON.stringify(report)) }];
